const fs = require("fs");
const path = require("path");

function cleanText(value) {
  return String(value ?? "").trim();
}

function safeReadJson(filePath, fallback) {
  try {
    if (!fs.existsSync(filePath)) return fallback;
    return JSON.parse(fs.readFileSync(filePath, "utf8"));
  } catch (error) {
    return fallback;
  }
}

function saveJson(filePath, data) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), "utf8");
}

const archivo = $("Buscar programaciones Audi").first().json;
const contexto = $("Preparar archivo trigger").first().json;
const remisiones = $("Asignar no.Rem PG").all();

const estadoPath = cleanText(archivo.estado_procesados_path);
const processedKey = cleanText(archivo.processed_key);

if (!estadoPath) {
  throw new Error("No se encontró estado_procesados_path desde 'Buscar programaciones Audi'.");
}

if (!processedKey) {
  throw new Error("No se encontró processed_key desde 'Buscar programaciones Audi'.");
}

const estadoDefault = {
  cliente: "AUDI",
  updated_at: "",
  procesados: {}
};

const estado = safeReadJson(estadoPath, estadoDefault);

if (!estado.procesados || typeof estado.procesados !== "object") {
  estado.procesados = {};
}

estado.procesados[processedKey] = {
  file_path: archivo.file_path || archivo.fullPath || archivo.path || "",
  file_name: archivo.file_name || archivo.fileName || "",
  size_bytes: archivo.size_bytes || "",
  modified_at: archivo.modified_at || "",

  processed_at: new Date().toISOString(),
  status: "procesado_correctamente",

  run_name: contexto.run_name || "",
  copied_file: contexto.copy_file_path || "",

  remisiones_generadas: remisiones.length,
  primera_remision: remisiones[0]?.json?.numero_remision || "",
  ultima_remision: remisiones[remisiones.length - 1]?.json?.numero_remision || "",

  hojas_identificacion_generadas: remisiones.length,

  postgres: {
    ejecucion_id: remisiones[0]?.json?.ejecucion_id || "",
    folios_pg: remisiones[0]?.json?.pg_folios === true,
    folio_inicial_reservado: remisiones[0]?.json?.folio_inicial_reservado || "",
    folio_final_reservado: remisiones[0]?.json?.folio_final_reservado || ""
  }
};

estado.updated_at = new Date().toISOString();
estado.total_procesados = Object.keys(estado.procesados).length;

saveJson(estadoPath, estado);

return $input.all();

const fs = require("fs");
const path = require("path");

// ===============================
// CONFIGURACIÓN
// ===============================
const BASE_CLIENTE_AUDI = String.raw`C:\Users\06\Documents\Dropbox\Pruebas\REMISIONES AUDI\00_ARCHIVOS A PROCESAR`;

const BASE_HERRAMIENTA = String.raw`C:\Users\06\Documents\Dropbox\Pruebas\REMISIONES AUDI`;

const ESTADO_PATH = `${BASE_HERRAMIENTA}\\05_ARCHIVOS AUXILIARES\\ESTADO\\archivos_procesados_audi.json`;

// Para evitar leer un archivo que Dropbox todavía está copiando
const MIN_AGE_MINUTES = 2;

// Para no tomar programaciones viejas por accidente.
// Si algún día necesitas buscar más atrás, sube este número.
const MAX_AGE_DAYS = 60;

// IMPORTANTE:
// Ponlo en true solo una vez si quieres marcar todos los archivos actuales como ya procesados.
// Después vuelve a ponerlo en false antes de publicar.
const MODO_INICIALIZAR_ESTADO = false;

// Procesamos solo 1 archivo por corrida para evitar problemas con contador.
const MAX_FILES_PER_RUN = 1;

// ===============================
// FUNCIONES
// ===============================
function cleanText(value) {
  return String(value ?? "").trim();
}

function removeAccents(value) {
  return cleanText(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function normalizeText(value) {
  return removeAccents(value)
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function normalizePath(value) {
  return normalizeText(value)
    .replace(/\//g, "\\")
    .replace(/\\+/g, "\\");
}

function safeReadJson(filePath, fallback) {
  try {
    if (!fs.existsSync(filePath)) return fallback;
    const content = fs.readFileSync(filePath, "utf8");
    return JSON.parse(content);
  } catch (error) {
    return fallback;
  }
}

function saveJson(filePath, data) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), "utf8");
}

function isYearFolder(name) {
  return /^20\d{2}$/.test(cleanText(name));
}

function shouldCheckYear(yearText) {
  const year = Number(yearText);
  const currentYear = new Date().getFullYear();

  // Revisa año anterior, actual y siguiente.
  // Esto ayuda cuando estamos en transición de año.
  return year >= currentYear - 1 && year <= currentYear + 1;
}

function isInfoAdicionalFolder(folderName) {
  const name = normalizeText(folderName);

  const hasInfo =
    name.includes("inf") ||
    name.includes("info") ||
    name.includes("informacion") ||
    name.includes("informacion");

  const hasAdicional =
    name.includes("adicional") ||
    name.includes("adic");

  return hasInfo && hasAdicional;
}

function isValidProgramacionFile(filePath) {
  const fileName = path.basename(filePath);
  const lowerName = normalizeText(fileName);

  const isExcel = lowerName.endsWith(".xlsx");
  const isTemp = lowerName.startsWith("~$");

  const isProgramacion =
    lowerName.includes("programacion de entrega") ||
    lowerName.includes("programacion_de_entrega");

  const isAudi =
    lowerName.includes("audi") ||
    normalizePath(filePath).includes("\\clientes\\audi\\");

  return isExcel && !isTemp && isProgramacion && isAudi;
}

function getFileAgeMinutes(stats) {
  return (Date.now() - stats.mtimeMs) / 1000 / 60;
}

function getFileAgeDays(stats) {
  return getFileAgeMinutes(stats) / 60 / 24;
}

function getProcessedKey(filePath) {
  // Usamos ruta como llave para evitar reprocesar el mismo archivo cada 15 min.
  // Si algún día se quiere reprocesar, se puede borrar esta entrada del JSON.
  return normalizePath(path.resolve(filePath));
}

function walkForExcelFiles(dir, results = []) {
  if (!fs.existsSync(dir)) return results;

  let entries = [];

  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (error) {
    return results;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      const folderName = normalizeText(entry.name);

      // Evita meterse en carpetas claramente irrelevantes
      if (
        folderName.includes("remisiones") ||
        folderName.includes("facturas") ||
        folderName.includes("recibida") ||
        folderName.includes("recibidas")
      ) {
        continue;
      }

      walkForExcelFiles(fullPath, results);
      continue;
    }

    if (!entry.isFile()) continue;

    if (isValidProgramacionFile(fullPath)) {
      try {
        const stats = fs.statSync(fullPath);

        const ageMinutes = getFileAgeMinutes(stats);
        const ageDays = getFileAgeDays(stats);

        if (ageMinutes < MIN_AGE_MINUTES) continue;
        if (ageDays > MAX_AGE_DAYS) continue;

        results.push({
          file_path: fullPath,
          file_name: path.basename(fullPath),
          size_bytes: stats.size,
          modified_at: stats.mtime.toISOString(),
          modified_time_ms: stats.mtimeMs,
          processed_key: getProcessedKey(fullPath)
        });
      } catch (error) {
        continue;
      }
    }
  }

  return results;
}

// ===============================
// BUSCAR CANDIDATOS
// ===============================
if (!fs.existsSync(BASE_CLIENTE_AUDI)) {
  throw new Error(`No existe la carpeta base de Audi: ${BASE_CLIENTE_AUDI}`);
}

const estadoDefault = {
  cliente: "AUDI",
  updated_at: "",
  procesados: {}
};

const estado = safeReadJson(ESTADO_PATH, estadoDefault);

if (!estado.procesados || typeof estado.procesados !== "object") {
  estado.procesados = {};
}

const yearFolders = fs.readdirSync(BASE_CLIENTE_AUDI, { withFileTypes: true })
  .filter(entry => entry.isDirectory())
  .map(entry => entry.name)
  .filter(name => isYearFolder(name))
  .filter(name => shouldCheckYear(name));

const candidatos = [];

for (const yearFolder of yearFolders) {
  const yearPath = path.join(BASE_CLIENTE_AUDI, yearFolder);

  let subfolders = [];

  try {
    subfolders = fs.readdirSync(yearPath, { withFileTypes: true })
      .filter(entry => entry.isDirectory())
      .map(entry => entry.name);
  } catch (error) {
    continue;
  }

  const infoFolders = subfolders.filter(isInfoAdicionalFolder);

  for (const infoFolder of infoFolders) {
    const infoPath = path.join(yearPath, infoFolder);
    walkForExcelFiles(infoPath, candidatos);
  }
}

// Ordena del más antiguo al más reciente
candidatos.sort((a, b) => a.modified_time_ms - b.modified_time_ms);

// ===============================
// MODO INICIALIZAR ESTADO
// ===============================
if (MODO_INICIALIZAR_ESTADO) {
  for (const file of candidatos) {
    estado.procesados[file.processed_key] = {
      file_path: file.file_path,
      file_name: file.file_name,
      size_bytes: file.size_bytes,
      modified_at: file.modified_at,
      processed_at: new Date().toISOString(),
      status: "marcado_como_existente"
    };
  }

  estado.updated_at = new Date().toISOString();
  estado.total_procesados = Object.keys(estado.procesados).length;

  saveJson(ESTADO_PATH, estado);

  return [];
}

// ===============================
// FILTRAR NO PROCESADOS
// ===============================
const nuevos = candidatos.filter(file => !estado.procesados[file.processed_key]);

const seleccionados = nuevos.slice(0, MAX_FILES_PER_RUN);

return seleccionados.map(file => ({
  json: {
    path: file.file_path,
    filePath: file.file_path,
    fullPath: file.file_path,
    file_name: file.file_name,
    fileName: file.file_name,

    size_bytes: file.size_bytes,
    modified_at: file.modified_at,

    processed_key: file.processed_key,
    estado_procesados_path: ESTADO_PATH,

    archivo_valido: true,
    deteccion_modo: "schedule_audi",
    candidatos_encontrados: candidatos.length,
    archivos_nuevos_pendientes: nuevos.length
  }
}));

function cleanText(value) {
  return String(value ?? "")
    .replace(/\t/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeHeader(value) {
  return cleanText(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "_");
}

function normalizePartNumber(value) {
  return cleanText(value)
    .toUpperCase()
    .replace(/\s+/g, "");
}

function rowToArray(row) {
  if (Array.isArray(row)) return row;
  if (Array.isArray(row.row)) return row.row;
  if (Array.isArray(row.data)) return row.data;
  if (Array.isArray(row.values)) return row.values;

  const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

  if (Object.keys(row).some(key => /^[A-Z]+$/.test(key))) {
    return letters.map(letter => row[letter] ?? "");
  }

  return Object.values(row);
}

function isUnit(value) {
  const text = cleanText(value).toLowerCase();

  return [
    "bag",
    "bags",
    "kg",
    "kgs",
    "kilo",
    "kilos",
    "roll",
    "rolls",
    "rollo",
    "rollos",
    "pack",
    "packs",
    "paquete",
    "paquetes"
  ].includes(text);
}

function normalizeUnit(value) {
  const text = cleanText(value).toLowerCase();

  if (["bag", "bags", "bolsa", "bolsas"].includes(text)) return "bags";
  if (["kg", "kgs", "kilo", "kilos"].includes(text)) return "kg";
  if (["roll", "rolls", "rollo", "rollos"].includes(text)) return "Roll";
  if (["pack", "packs", "paquete", "paquetes"].includes(text)) return "packs";

  return cleanText(value);
}

function isExcelDateSerial(value) {
  const number = Number(value);
  return Number.isFinite(number) && number >= 30000 && number <= 60000;
}

function excelSerialToISODate(serial) {
  const excelEpoch = Date.UTC(1899, 11, 30);
  const ms = excelEpoch + Math.floor(Number(serial)) * 86400 * 1000;
  const date = new Date(ms);

  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

const rawRows = $input.all().map(item => rowToArray(item.json));

let headerIndex = -1;
let headers = [];

for (let i = 0; i < rawRows.length; i++) {
  const normalized = rawRows[i].map(normalizeHeader);

  const hasActivo = normalized.includes("activo");
  const hasPartNumber = normalized.includes("part_number");

  if (hasActivo && hasPartNumber) {
    headerIndex = i;
    headers = normalized;
    break;
  }
}

if (headerIndex === -1) {
  throw new Error("No se encontró la fila de encabezados del catálogo. Debe existir una fila con columnas 'activo' y 'part_number'.");
}

function getByHeader(row, name) {
  const index = headers.indexOf(name);
  if (index === -1) return "";
  return row[index] ?? "";
}

const catalogo = {};

for (let i = headerIndex + 1; i < rawRows.length; i++) {
  const row = rawRows[i];

  const activo = cleanText(getByHeader(row, "activo")).toUpperCase();

  if (!activo) continue;
  if (activo !== "SI") continue;

  const partNumber = cleanText(getByHeader(row, "part_number"));

  const partNumberNormalizado = normalizePartNumber(
    getByHeader(row, "part_number_normalizado") || partNumber
  );

  if (!partNumberNormalizado) continue;

  let packingCode = cleanText(getByHeader(row, "packing_code"));
  let unidadBase = cleanText(getByHeader(row, "unidad_base"));
  let qtyPerPackagingDefault = cleanText(getByHeader(row, "qty_per_packaging_default"));
  let observaciones = cleanText(getByHeader(row, "observaciones"));
  let fechaActualizacion = cleanText(getByHeader(row, "fecha_actualizacion"));

  /*
    Corrección automática para casos donde las columnas quedaron corridas:
    packing_code = bags
    unidad_base = 40
    qty_per_packaging_default = 46210
  */
  if (isUnit(packingCode)) {
    const unidadDetectada = normalizeUnit(packingCode);

    packingCode = "";

    if (!isUnit(unidadBase)) {
      const posibleQty = unidadBase;
      unidadBase = unidadDetectada;

      if (posibleQty && !qtyPerPackagingDefault) {
        qtyPerPackagingDefault = posibleQty;
      } else if (posibleQty && isExcelDateSerial(qtyPerPackagingDefault)) {
        fechaActualizacion = excelSerialToISODate(qtyPerPackagingDefault);
        qtyPerPackagingDefault = posibleQty;
      }
    } else {
      unidadBase = normalizeUnit(unidadBase);
    }
  } else {
    unidadBase = normalizeUnit(unidadBase);
  }

  if (isExcelDateSerial(fechaActualizacion)) {
    fechaActualizacion = excelSerialToISODate(fechaActualizacion);
  }

  if (isExcelDateSerial(qtyPerPackagingDefault) && !fechaActualizacion) {
    fechaActualizacion = excelSerialToISODate(qtyPerPackagingDefault);
    qtyPerPackagingDefault = "";
  }

  catalogo[partNumberNormalizado] = {
    activo,
    part_number: partNumber,
    part_number_normalizado: partNumberNormalizado,

    codigo_interno: cleanText(getByHeader(row, "codigo_interno")),
    descripcion_catalogo: cleanText(getByHeader(row, "descripcion_catalogo")),
    formato_audi: cleanText(getByHeader(row, "formato_audi")).toLowerCase(),

    pde: cleanText(getByHeader(row, "pde")),
    ref_pedido: cleanText(getByHeader(row, "ref_pedido")),

    discharge_point: cleanText(getByHeader(row, "discharge_point")),
    packing_code: packingCode,
    unidad_base: unidadBase,
    qty_per_packaging_default: qtyPerPackagingDefault,
    observaciones,
    fecha_actualizacion: fechaActualizacion
  };
}

return [
  {
    json: {
      catalogo_productos: catalogo,
      total_productos_catalogo: Object.keys(catalogo).length,
      catalogo_productos_path: $("Preparar archivo trigger").first().json.catalogo_productos_path
    }
  }
];

const remisiones = $("Normalizar datos").all();

if (remisiones.length === 0) {
  throw new Error("No hay remisiones generadas por el nodo 'Normalizar datos'.");
}

const counterItem = $input.first();

if (!counterItem) {
  throw new Error("No llegó ningún item con el archivo contador.");
}

const binaryField = Object.keys(counterItem.binary || {})[0] || "data";

if (!counterItem.binary || !counterItem.binary[binaryField]) {
  throw new Error("No se encontró el archivo contador en binario. Revisa el nodo que lee contador_remisiones_audi.json.");
}

const counterBuffer = await this.helpers.getBinaryDataBuffer(0, binaryField);

let counter;

try {
  counter = JSON.parse(counterBuffer.toString("utf8"));
} catch (error) {
  throw new Error("No se pudo leer contador_remisiones_audi.json como JSON válido.");
}

const lastRemision = Number(counter.last_remision);

if (!Number.isInteger(lastRemision) || lastRemision < 1) {
  throw new Error("El contador last_remision no es válido: " + counter.last_remision);
}

function cleanText(value) {
  return String(value ?? "").trim();
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

function formatRemisionNumber(value) {
  return String(value).padStart(4, "0");
}

function normalizePartNumber(partNumber) {
  return cleanText(partNumber)
    .toUpperCase()
    .replace(/\s+/g, "");
}

function shortPartName(partNumber) {
  const normalized = normalizePartNumber(partNumber);

  const manualNames = {
    "A156729": "156729",
    "A156730": "156730",
    "A15M3M6": "M3M6",
    "A15M1M7": "M1M7",
    "A15MEAW": "15MEAW",
    "A15MEAV": "15MEAV"
  };

  if (manualNames[normalized]) {
    return manualNames[normalized];
  }

  // Fallback genérico:
  // A 123456 -> 123456
  // A ABC123 -> ABC123
  const withoutA = normalized.replace(/^A/, "");

  return withoutA || safeFileText(partNumber);
}

const newLastRemision = lastRemision + remisiones.length;

return remisiones.map((item, index) => {
  const json = { ...item.json };

  const folioNumber = lastRemision + index + 1;
  const folioText = formatRemisionNumber(folioNumber);

  const partNumber =
    json.part_number ||
    json.items?.[0]?.part_number ||
    "";

  const partShort = shortPartName(partNumber);

  json.remision_folio_numero = folioNumber;
  json.numero_remision = folioText;

  // Nombre final del HTML. El PDF tomará el mismo nombre cambiando .html por .pdf.
  json.output_name = `Rem ${folioText} ${safeFileText(partShort)}.html`;

  // Usa la ruta que viene desde Preparar archivo trigger / Normalizar datos.
  json.counter_path =
    json.counter_path ||
    "C:\\Users\\06\\Documents\\Dropbox\\Herramientas\\Remisiones Audi\\05_Archivos auxiliares\\Estado\\contador_remisiones_audi.json";

  json.counter_previous = lastRemision;
  json.counter_new_last = newLastRemision;

  json.counter_cliente = counter.cliente || "AUDI";
  json.counter_updated_at_previous = counter.updated_at || "";

  return { json };
});

const remisiones = $("Asignar no.Rem").all();

if (remisiones.length === 0) {
  throw new Error("No hay remisiones para actualizar contador.");
}

const first = remisiones[0].json;

const counterPath = first.counter_path;
const newLast = Number(first.counter_new_last);
const previousLast = Number(first.counter_previous);

if (!counterPath) {
  throw new Error("No se encontró counter_path. Revisa que venga desde 'Preparar archivo trigger' y 'Asignar no.Rem'.");
}

if (!Number.isInteger(newLast) || newLast < 1) {
  throw new Error("counter_new_last no es válido: " + first.counter_new_last);
}

if (!Number.isInteger(previousLast) || previousLast < 1) {
  throw new Error("counter_previous no es válido: " + first.counter_previous);
}

const remisionesGeneradas = remisiones.map(item => {
  const json = item.json;

  return {
    numero_remision: json.numero_remision,
    remision_folio_numero: json.remision_folio_numero,
    part_number: json.part_number,
    codigo_interno: json.codigo_interno,
    output_name: json.output_name || "",
    pdf_name: json.pdf_name || ""
  };
});

const counter = {
  cliente: "AUDI",
  last_remision: newLast,
  previous_last_remision: previousLast,
  remisiones_generadas: remisiones.length,
  updated_at: new Date().toISOString(),
  last_run_name: first.run_name || "",
  last_source_file: first.archivo_origen || first.file_path || "",
  last_copied_file: first.archivo_copiado || "",
  remisiones: remisionesGeneradas
};

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(JSON.stringify(counter, null, 2), "utf8"),
  "contador_remisiones_audi.json",
  "application/json"
);

return [
  {
    json: {
      counter_path: counterPath,
      last_remision: newLast,
      previous_last_remision: previousLast,
      remisiones_generadas: remisiones.length,
      run_name: first.run_name || "",
      archivo_origen: first.archivo_origen || first.file_path || "",
      archivo_copiado: first.archivo_copiado || ""
    },
    binary: {
      data: binaryData
    }
  }
];

const BASE_HERRAMIENTA = String.raw`C:\Users\06\Documents\Dropbox\Pruebas\REMISIONES AUDI`;

function cleanText(value) {
  return String(value ?? "").trim();
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/\.[^.]+$/i, "")
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

function pad(value) {
  return String(value).padStart(2, "0");
}

function getTimestamp() {
  const now = new Date();

  return (
    `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_` +
    `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`
  );
}

function getFileNameFromPath(filePath) {
  return cleanText(filePath).split(/[\\/]/).pop();
}

const timestamp = getTimestamp();

// ===============================
// Carpetas principales
// ===============================
const copyDir = `${BASE_HERRAMIENTA}\\01_ENTRADA`;

const salidasDir = `${BASE_HERRAMIENTA}\\02_SALIDAS`;
const remisionesDir = `${salidasDir}\\REMISIONES`;
const hojasIdentificacionDir = `${salidasDir}\\HOJAS_IDENTIFICACION`;

const logsDir = `${BASE_HERRAMIENTA}\\03_LOGS`;
const errorDir = `${BASE_HERRAMIENTA}\\04_ERRORES`;

const auxiliaresDir = `${BASE_HERRAMIENTA}\\05_ARCHIVOS AUXILIARES`;
const templatesDir = `${auxiliaresDir}\\TEMPLATES`;
const scriptsDir = `${auxiliaresDir}\\SCRIPTS`;
const estadoDir = `${auxiliaresDir}\\ESTADO`;
const catalogoDir = `${auxiliaresDir}\\CATALOGO`;

const tempBaseDir = `${BASE_HERRAMIENTA}\\06_ARCHIVOS TEMPORALES`;
const tempDir = `${tempBaseDir}\\html`;
