function rowToArray(row) {
  if (Array.isArray(row)) return row;
  if (Array.isArray(row.row)) return row.row;
  if (Array.isArray(row.data)) return row.data;
  if (Array.isArray(row.values)) return row.values;

  const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

  if (Object.keys(row).some(key => /^[A-Z]+$/.test(key))) {
    return letters.map(letter => row[letter] ?? "");
  }

  const columnKeys = Object.keys(row)
    .filter(key => /(\d+)$/.test(key))
    .sort((a, b) => {
      const na = Number(a.match(/(\d+)$/)?.[1] ?? 0);
      const nb = Number(b.match(/(\d+)$/)?.[1] ?? 0);
      return na - nb;
    });

  if (columnKeys.length) {
    return columnKeys.map(key => row[key] ?? "");
  }

  return Object.values(row);
}

const rows = inputRows.map(rowToArray);

const meses = [
  "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
  "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
];

function excelSerialToDateParts(serial) {
  const excelEpoch = Date.UTC(1899, 11, 30);
  const ms = excelEpoch + Math.floor(Number(serial)) * 86400 * 1000;
  const date = new Date(ms);

  return {
    day: date.getUTCDate(),
    month: date.getUTCMonth(),
    year: date.getUTCFullYear()
  };
}

function formatDateSpanish(value) {
  if (value === null || value === undefined || value === "") return "";

  if (typeof value === "number") {
    const { day, month, year } = excelSerialToDateParts(value);
    return `${day} de ${meses[month]} de ${year}`;
  }

  if (value instanceof Date) {
    return `${value.getUTCDate()} de ${meses[value.getUTCMonth()]} de ${value.getUTCFullYear()}`;
  }

  const text = String(value).trim();

  const match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) {
    const [, dd, mm, yyyy] = match;
    return `${Number(dd)} de ${meses[Number(mm) - 1]} de ${Number(yyyy)}`;
  }

  return text;
}

function cleanText(value) {
  return String(value ?? "")
    .replace(/\t/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

function normalizePartNumber(value) {
  return cleanText(value)
    .toUpperCase()
    .replace(/\s+/g, "");
}

function cleanDescription(description, partNumber) {
  let text = String(description ?? "")
    .replace(/\s*COD SAP:\s*\d+/gi, "")
    .replace(/\s+/g, " ")
    .trim();

  const part = cleanText(partNumber)
    .replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

  if (part) {
    text = text.replace(new RegExp(`^${part}\\s*-?\\s*`, "i"), "").trim();
  }

  return text;
}

function normalizeFormatoAudi(value) {
  const text = cleanText(value).toLowerCase();

  if (["tubo", "tubos", "rollo", "rollos", "kg"].includes(text)) return "tubos";

  if (["bolsa", "bolsas", "bag", "bags", "pack", "packs", "paquete", "paquetes"].includes(text)) {
    return "bolsas";
  }

  return "";
}

const NUMBER_PATTERN = String.raw`\d+(?:[.,]\d+)*`;

function numberUnitRegex(unitPattern) {
  return new RegExp(`(${NUMBER_PATTERN})\\s*(?:${unitPattern})`, "i");
}

function parseFlexibleNumber(value) {
  const text = String(value ?? "").trim();

  if (!text) return NaN;

  if (text.includes(",") && text.includes(".")) {
    return text.lastIndexOf(",") > text.lastIndexOf(".")
      ? Number(text.replace(/\./g, "").replace(",", "."))
      : Number(text.replace(/,/g, ""));
  }

  if (text.includes(",")) {
    const parts = text.split(",");

    if (parts.length === 2 && parts[1].length === 3) {
      return Number(parts[0] + parts[1]);
    }

    return Number(text.replace(",", "."));
  }

  if (text.includes(".")) {
    const parts = text.split(".");

    if (parts.length === 2 && parts[1].length === 3) {
      return Number(parts[0] + parts[1]);
    }

    return Number(text);
  }

  return Number(text);
}

function formatCalculatedNumber(value) {
  if (!Number.isFinite(value)) return "";

  const rounded = Math.round((value + Number.EPSILON) * 1000) / 1000;

  if (Number.isInteger(rounded)) return String(rounded);

  return rounded.toFixed(3).replace(/\.?0+$/, "");
}

function parseCantidadNumerica(value) {
  const text = cleanText(value);

  const result = {
    total_numeros: 0,
    total_valor: 0
  };

  if (!text) return result;

  if (/^0+(?:[.,]0+)?$/i.test(text)) {
    return {
      total_numeros: 1,
      total_valor: 0
    };
  }

  const regex = /([\d.,]+)\s*(bolsas?|bags?|rollos?|rolls?|paquetes?|packs?|kg|kgs|kilo|kilos)/gi;

  let match;

  while ((match = regex.exec(text)) !== null) {
    const number = parseFlexibleNumber(match[1]);

    if (!Number.isFinite(number)) continue;

    result.total_numeros += 1;
    result.total_valor += number;
  }

  return result;
}

function isCantidadCero(value) {
  const parsed = parseCantidadNumerica(value);
  return parsed.total_numeros > 0 && parsed.total_valor === 0;
}

function parseCantidad(value) {
  const text = cleanText(value);

  const parts = text.split("=").map(p => cleanText(p));
  const left = parts[0] || "";
  const right = parts[1] || "";

  const bolsasMatch = text.match(numberUnitRegex("bolsas?"));
  const rollLeftMatch = left.match(numberUnitRegex("rolls?|rollos?"));
  const rollRightMatch = right.match(numberUnitRegex("rolls?|rollos?"));
  const packRightMatch = right.match(numberUnitRegex("packs?|paquetes?"));
  const kgRightMatch = right.match(numberUnitRegex("kg|kgs|kilo|kilos"));

  if (bolsasMatch && rollRightMatch) {
    return {
      total_qty: `${rollRightMatch[1]} Roll`,
      entrega_text: `${rollRightMatch[1]} rollos`,
      number_of_bags: `${bolsasMatch[1]} bags`
    };
  }

  if (bolsasMatch && packRightMatch) {
    return {
      total_qty: `${packRightMatch[1]} packs`,
      entrega_text: `${packRightMatch[1]} packs`,
      number_of_bags: `${bolsasMatch[1]} bags`
    };
  }

  if (rollLeftMatch && kgRightMatch) {
    return {
      total_qty: `${rollLeftMatch[1]} Roll`,
      entrega_text: `${rollLeftMatch[1]} rollos`,
      number_of_bags: `${kgRightMatch[1]} Kg`
    };
  }

  return {
    total_qty: text,
    entrega_text: text,
    number_of_bags: ""
  };
}

function getQtyPerPackaging(description, cantidadRaw, productoCatalogo) {
  const desc = cleanText(description);
  const cantidad = cleanText(cantidadRaw);

  let match = desc.match(new RegExp(`(?:rolls?|rollos?)\\s*c\\/\\s*(${NUMBER_PATTERN})\\s*bolsas?`, "i"));
  if (match) return `${match[1]} bags per roll`;

  match = desc.match(new RegExp(`(?:packs?|paquetes?)\\s*c\\/\\s*(${NUMBER_PATTERN})\\s*bolsas?`, "i"));
  if (match) return `${match[1]} bags per pack`;

  const bolsasMatch = cantidad.match(numberUnitRegex("bolsas?"));

  const rollCantidadMatch = cantidad.match(new RegExp(`=\\s*(${NUMBER_PATTERN})\\s*(?:rolls?|rollos?)`, "i"));
  const packCantidadMatch = cantidad.match(new RegExp(`=\\s*(${NUMBER_PATTERN})\\s*(?:packs?|paquetes?)`, "i"));

  if (bolsasMatch && rollCantidadMatch) {
    const bolsas = parseFlexibleNumber(bolsasMatch[1]);
    const rollos = parseFlexibleNumber(rollCantidadMatch[1]);
    return `${formatCalculatedNumber(bolsas / rollos)} bags per roll`;
  }

  if (bolsasMatch && packCantidadMatch) {
    const bolsas = parseFlexibleNumber(bolsasMatch[1]);
    const packs = parseFlexibleNumber(packCantidadMatch[1]);
    return `${formatCalculatedNumber(bolsas / packs)} bags per pack`;
  }

  const rollKgMatch = cantidad.match(
    new RegExp(`(${NUMBER_PATTERN})\\s*(?:rolls?|rollos?).*=\\s*(${NUMBER_PATTERN})\\s*(?:kg|kgs|kilo|kilos)`, "i")
  );

  if (rollKgMatch) {
    const rollos = parseFlexibleNumber(rollKgMatch[1]);
    const kg = parseFlexibleNumber(rollKgMatch[2]);
    return `${formatCalculatedNumber(kg / rollos)} Kg per roll`;
  }

  return cleanText(productoCatalogo?.qty_per_packaging_default);
}

function getPedidoFromNotas(notas) {
  const text = cleanText(notas);

  const pedidoMatch = text.match(/(?:pedido|ref)[^\d]*(\d{8,})/i);
  if (pedidoMatch) return pedidoMatch[1];

  const anyLongNumber = text.match(/\b(7\d{8,})\b/);
  if (anyLongNumber) return anyLongNumber[1];

  return "";
}

function getPdeFromNotas(notas) {
  const text = cleanText(notas);

  const pdeMatch = text.match(/PDE[^\d]*(\d{8,})/i);
  if (pdeMatch) return pdeMatch[1];

  return "";
}

