function cleanText(value) {
  return String(value ?? "").trim();
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

function formatRemisionNumber(value) {
  return String(value).padStart(4, "0");
}

function normalizePartNumber(partNumber) {
  return cleanText(partNumber)
    .toUpperCase()
    .replace(/\s+/g, "");
}

function shortPartName(partNumber) {
  const normalized = normalizePartNumber(partNumber);

  const manualNames = {
    "A156729": "156729",
    "A156730": "156730",
    "A15M3M6": "M3M6",
    "A15M1M7": "M1M7",
    "A15MEAW": "15MEAW",
    "A15MEAV": "15MEAV"
  };

  if (manualNames[normalized]) return manualNames[normalized];

  return normalized.replace(/^A/, "") || safeFileText(partNumber);
}

return remisiones.map((item, index) => {
  const json = { ...item.json };

  const folioNumber = folioInicial + index;
  const folioText = formatRemisionNumber(folioNumber);

