function pdfNameFromOutputName(outputName) {
  const name = cleanText(outputName);
  if (!name) return "";
  return name.replace(/\.html?$/i, ".pdf");
}

function joinPath(dir, file) {
  if (!dir || !file) return "";
  return cleanText(dir).replace(/[\\/]$/, "") + "\\" + cleanText(file);
}

function parseNumber(value) {
  const text = cleanText(value);
  if (!text) return NaN;

  if (text.includes(",") && text.includes(".")) {
    return text.lastIndexOf(",") > text.lastIndexOf(".")
      ? Number(text.replace(/\./g, "").replace(",", "."))
      : Number(text.replace(/,/g, ""));
  }

  if (text.includes(",")) {
    const parts = text.split(",");
    return parts.length === 2 && parts[1].length === 3
      ? Number(parts[0] + parts[1])
      : Number(text.replace(",", "."));
  }

  return Number(text);
}

function getKgFromCantidad(text) {
  const match = cleanText(text).match(/([\d.,]+)\s*(kg|kgs|kilo|kilos)/i);
  if (!match) return 0;

  const kg = parseNumber(match[1]);
  return Number.isFinite(kg) ? kg : 0;
}

function countHojasIdentificacion(remisiones) {
  let total = 0;

  for (const rem of remisiones) {
    const kg = getKgFromCantidad(rem.cantidad_excel);

    if (kg > 600) {
      total += Math.ceil(kg / 600);
    } else {
      total += 1;
    }
  }

  return total;
}

function fechaArchivoHI(base) {
  const source = cleanText(
    base.source_base_name ||
    base.file_name ||
    base.run_name ||
    ""
  );

  const matchAudiDate = source.match(/AUDI[_\s-]*(\d{6})/i);

  if (matchAudiDate) {
    const value = matchAudiDate[1];
    return `20${value.slice(0, 2)}${value.slice(2, 4)}${value.slice(4, 6)}`;
  }

  const timestamp = cleanText(base.timestamp);
  if (/^\d{8}/.test(timestamp)) return timestamp.slice(0, 8);

  const now = new Date();

  return `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}`;
}

