}

function sqlNullableText(value) {
  const text = cleanText(value);
  return text ? sqlText(text) : "NULL";
}

function parseFechaDocumento(value) {
  const text = cleanText(value);

  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;

  const matchIso = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (matchIso) return `${matchIso[1]}-${matchIso[2]}-${matchIso[3]}`;

  const meses = {
    enero: "01",
    febrero: "02",
    marzo: "03",
    abril: "04",
    mayo: "05",
    junio: "06",
    julio: "07",
    agosto: "08",
    septiembre: "09",
    setiembre: "09",
    octubre: "10",
    noviembre: "11",
    diciembre: "12"
  };

  const lower = text.toLowerCase();
  const matchEsp = lower.match(/(\d{1,2})\s+de\s+([a-záéíóúñ]+)\s+de\s+(\d{4})/i);

  if (matchEsp) {
    const dia = String(matchEsp[1]).padStart(2, "0");
    const mes = meses[matchEsp[2].normalize("NFD").replace(/[\u0300-\u036f]/g, "")];
    const anio = matchEsp[3];

    if (mes) return `${anio}-${mes}-${dia}`;
  }

  throw new Error("No se pudo convertir fecha_documento a DATE: " + text);
}

function pdfNameFromOutputName(outputName) {
  const name = cleanText(outputName);
  if (!name) return "";
  return name.replace(/\.html?$/i, ".pdf");
}

function joinPath(dir, file) {
  if (!dir || !file) return "";
  return cleanText(dir).replace(/[\\/]$/, "") + "\\" + cleanText(file);
}

const remisionesItems = $("Asignar no.Rem PG").all();

if (!remisionesItems.length) {
  throw new Error("No hay remisiones para registrar en PostgreSQL.");
}

const pgRun = $("Propagar ejecución PG").first().json;
const pgConfig = $("Validar configuración PostgreSQL").first().json;
const contexto = $("Preparar archivo trigger").first().json;

const serieId = Number(pgConfig.serie_id || pgRun.serie_id);
const empresaClienteId = Number(pgRun.empresa_cliente_id);
const ejecucionId = Number(pgRun.ejecucion_id);

if (!serieId) throw new Error("serie_id inválido.");
if (!empresaClienteId) throw new Error("empresa_cliente_id inválido.");
if (!ejecucionId) throw new Error("ejecucion_id inválido.");

const remisionesDir =
  contexto.remisiones_dir ||
  contexto.output_dir ||
  "";

const values = remisionesItems.map((item) => {
  const j = item.json || {};

  const folio = Number(j.remision_folio_numero);
  if (!folio) throw new Error("remision_folio_numero inválido.");

  const fechaDocumento = parseFechaDocumento(
    j.fecha_documento ||
    j.fecha_envio ||
    contexto.fecha_documento ||
    contexto.fecha_envio
  );

  const outputName = cleanText(j.output_name);
  const pdfName = cleanText(j.pdf_name) || pdfNameFromOutputName(outputName);
  const pdfPath = cleanText(j.pdf_path) || joinPath(remisionesDir, pdfName);

  const codigoInterno = j.codigo_interno || j.items?.[0]?.codigo_interno || "";
  const partNumber = j.part_number || j.items?.[0]?.part_number || "";
  const descripcion = j.descripcion_catalogo || j.descripcion || j.items?.[0]?.descripcion_catalogo || "";
  const cantidadTexto = j.cantidad_excel || j.items?.[0]?.cantidad_excel || "";

  if (!cantidadTexto) {
    throw new Error(`cantidad_texto vacía para folio ${folio}.`);
  }

  return `(
    ${folio},
    ${sqlText(fechaDocumento)},
    ${sqlNullableText(pdfPath)},
    ${sqlNullableText(codigoInterno)},
    ${sqlNullableText(partNumber)},
    ${sqlNullableText(descripcion)},
    ${sqlText(cantidadTexto)}
  )`;
}).join(",\n");

const sql = `
WITH input_data (
  folio,
  fecha_documento,
  pdf_path,
  codigo_interno,
  part_number,
  descripcion,
  cantidad_texto
) AS (
  VALUES
  ${values}
),
remisiones_insertadas AS (
  INSERT INTO operacion.remisiones (
    serie_id,
    folio,
    empresa_cliente_id,
    ejecucion_id,
    fecha_documento,
    pdf_path,
    estatus,
    created_at,
    updated_at
  )
  SELECT
    ${serieId},
    i.folio,
    ${empresaClienteId},
    ${ejecucionId},
    i.fecha_documento::date,
    i.pdf_path,
    'GENERADA',
    now(),
    now()
  FROM input_data i
  WHERE NOT EXISTS (
    SELECT 1
    FROM operacion.remisiones r
    WHERE r.serie_id = ${serieId}
      AND r.folio = i.folio
      AND r.estatus <> 'CANCELADA'
  )
  RETURNING
    remision_id,
    serie_id,
    folio,
    estatus,
    pdf_path
),
remisiones_insertadas_detalle AS (
  SELECT
    ri.remision_id,
    ri.serie_id,
    ri.folio,
    ri.estatus,
    ri.pdf_path,
    i.codigo_interno,
    i.part_number,
    i.descripcion,
    i.cantidad_texto
  FROM remisiones_insertadas ri
  JOIN input_data i
    ON i.folio = ri.folio
),
remisiones_existentes_detalle AS (
  SELECT
    r.remision_id,
    r.serie_id,
    r.folio,
    r.estatus,
    r.pdf_path,
    i.codigo_interno,
    i.part_number,
    i.descripcion,
    i.cantidad_texto
  FROM input_data i
  JOIN operacion.remisiones r
    ON r.serie_id = ${serieId}
   AND r.folio = i.folio
   AND r.estatus <> 'CANCELADA'
),
remisiones_final AS (
  SELECT * FROM remisiones_insertadas_detalle
  UNION ALL
  SELECT * FROM remisiones_existentes_detalle
),
detalles_insertados AS (
  INSERT INTO operacion.remision_detalle (
    remision_id,
    codigo_interno,
    part_number,
    descripcion,
    cantidad_texto,
    created_at
  )
  SELECT
    rf.remision_id,
    rf.codigo_interno,
    rf.part_number,
    rf.descripcion,
    rf.cantidad_texto,
    now()
  FROM remisiones_final rf
  WHERE NOT EXISTS (
    SELECT 1
    FROM operacion.remision_detalle d
    WHERE d.remision_id = rf.remision_id
  )
  RETURNING
    detalle_id,
    remision_id
),
detalle_final AS (
  SELECT
    d.remision_id,
    MIN(d.detalle_id) AS detalle_id,
    COUNT(*) AS detalles_totales
  FROM operacion.remision_detalle d
  JOIN remisiones_final rf
    ON rf.remision_id = d.remision_id
  GROUP BY d.remision_id
)
SELECT
  rf.remision_id,
  df.detalle_id,
  rf.serie_id,
  rf.folio,
  rf.estatus,
  rf.pdf_path,
  rf.codigo_interno,
  rf.part_number,
  rf.descripcion,
  rf.cantidad_texto,
  COALESCE(df.detalles_totales, 0) AS detalles_totales,
  (
    SELECT COUNT(*)
    FROM detalles_insertados di
    WHERE di.remision_id = rf.remision_id
  ) AS detalles_insertados
FROM remisiones_final rf
LEFT JOIN detalle_final df
  ON df.remision_id = rf.remision_id
ORDER BY rf.folio;
`;

return [
  {
    json: {
      sql_registrar_remisiones_pg: sql,
      remisiones_a_registrar: remisionesItems.length,
      ejecucion_id: ejecucionId,
      serie_id: serieId,
      empresa_cliente_id: empresaClienteId
    }
  }
];

